CREATE PROCEDURE [dbo].[codepage2] as DECLARE @Counter BIGINT SET @Counter = 0 DECLARE @THEMXR BIGINT SET @THEMXR = (SELECT MAX(CAST(CODE AS BIGINT) + 1) FROM  dbo.STUF_DEF) WHILE (@Counter <= (@THEMXR) ) BEGIN     UPDATE STUF_DEF SET    NAME =  REPLACE(REPLACE(CAST(NAME as nvarchar(4000)), NCHAR(1610), NCHAR(1740)), NCHAR(1603), NCHAR(1705))    WHERE CODE = N''+CONVERT(VARCHAR,@Counter)+''   SET @Counter += 1 End
